import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';

const IMMUNO_DISCLOSURE = {
  status: 'partial' as const,
  summary:
    'Secondary lymphoid organs (Thymus FMA9607 & Spleen FMA7196) connect directly to real 3D meshes in the BodyParts3D Atlas; cellular and cytokine pathways are presented via original 2D mechanistic schematics.',
};

function makeImmunoChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'immunology',
    chapterCode: `I${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['school_foundations', 'secondary_premed', 'medical_foundations', 'clinical_applied', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_gs_4_8', gradeOrYear: 'Grades 6–8', unitOrModule: `Immunity & Disease Protection (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grade XI', unitOrModule: `Immunity Lines of Defence (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Year 3', unitOrModule: `Immunology & Immunopathology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Molecular & Translational Immunology (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Eukaryotic organelles & secretion (B3)', 'Blood leukocytes & lymphoid microanatomy (C5, C9)'],
    learningObjectives: [
      `Trace the specific receptors, cells, and effector molecules executing ${chapterTitle.toLowerCase()}.`,
      `Explain how immune checkpoints and tolerance mechanisms prevent self-reactivity during ${chapterTitle.toLowerCase()}.`,
      `Connect dysregulation in ${chapterTitle.toLowerCase()} to immunodeficiencies, hypersensitivity, autoimmunity, or therapeutics.`,
    ],
    depthExplanations: {
      school_foundations: `${summary} Specialized white blood cells and barriers identify harmful germs cleanly without damaging healthy body cells.`,
      secondary_premed: `${summary} Coordinated signals between fast phagocytic cells and long-lived memory lymphocytes defend body organs continuously.`,
      medical_foundations: `${mechanisms.join(' ')} Clinical immunopathology: ${clinical}`,
      clinical_applied: `Bedside diagnosis and targeted biologics/vaccines exploit these immune checkpoints and effector mechanisms directly: ${clinical}`,
      graduate_research: `Structural TCR–pMHC binding kinetics, transcriptomic lineage fate switches (T-bet, GATA3, RORγt, FOXP3, Bcl-6), and checkpoint/CAR-T engineering underpin ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Primary Immune Mechanism', definition: summary },
      { term: 'Key Cells & Receptors', definition: mechanisms[0] ?? summary },
      { term: 'Clinical Relevance', definition: clinical },
    ],
    keyFacts: [
      mechanisms[0] ?? summary,
      'Real 3D Thymus (FMA9607) and Spleen (FMA7196) anatomical geometry can be inspected in the 3D Explorer alongside cellular pathway schematics.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Vaccines inject actual live illness or wear out the immune system.', correction: 'Modern vaccines train specific naive B and T clones safely with purified antigens or mRNA, building durable protective memory without full virulence.' },
      { misconception: 'MHC Class I and MHC Class II perform identical peptide presentation.', correction: 'MHC I monitors endogenous cytosolic proteins for CD8+ cytotoxic T killing; MHC II monitors phagocytosed exogenous antigens on professional APCs for CD4+ helper orchestration.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} elucidates authentic receptor–ligand immune cascades connecting innate recognition, adaptive memory, and clinical immunopathology.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      mechanisms[1] ?? clinical,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'microbiology_parasitology', relation: 'Immune defences target extracellular/intracellular bacteria, viruses, fungi, and helminths specifically.' },
      { domainId: 'pathology', relation: 'Unchecked inflammation, immune complexes, and granulomas drive host tissue injury.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['2d_diagram', '3d_anatomy', 'structured_text'],
    diagram: {
      id: `diag-i${num}`,
      title: `${chapterTitle} — Cellular & Molecular Pathway`,
      kind: 'pathway',
      caption: summary,
      disclaimer: 'Conceptual immunological schematic paired with 3D Thymus/Spleen meshes.',
      nodes: [
        { id: 'n1', label: 'Trigger / Sensor', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Receptor / Signalling Node', sublabel: mechanisms[1]?.slice(0, 62) || summary.slice(0, 62), tone: 'blue' },
        { id: 'n3', label: 'Effector / Clinical Consequence', sublabel: clinical.slice(0, 62), tone: 'teal' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Antigen / PAMP engagement' },
        { from: 'n2', to: 'n3', label: 'Lineage activation, lysis, or tolerance' },
      ],
    },
    assetDisclosure: IMMUNO_DISCLOSURE,
    activity: {
      title: `Immune Circuit Tracing Exercise (${chapterTitle})`,
      kind: 'interpretation',
      prompt: `Map the upstream trigger, cellular/receptor checkpoint, and downstream effector outcome in ${chapterTitle}, then predict the clinical consequence of selectively deleting the central receptor or enzyme.`,
      keyTakeaway: clinical,
    },
    readingKeys: ['ap_ch21_immune', 'micro_ch17_19_immuno'],
    shortAnswers: [
      { id: `sa-i${num}-1`, prompt: `Detail the sequential cellular and molecular mechanism in ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'medical_foundations' },
      { id: `sa-i${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB}.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'secondary_premed' },
      { id: `sa-i${num}-3`, prompt: `Connect a defect or therapeutic intervention in ${chapterTitle.toLowerCase()} to clinical human disease.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-i${num}-1`,
      title: `Immunology Clinical & Translational Reasoning: ${chapterTitle}`,
      scenario: `A teaching immunology vignette alters a single checkpoint molecule, MHC locus, or complement factor within ${chapterTitle.toLowerCase()}.`,
      questions: ['Which downstream effector arm fails or overreacts?', 'What susceptibility pattern or diagnostic biomarker results?'],
      workedSolution: `${mechanisms[0]} Outcome: ${clinical}`,
      level: 'medical_foundations',
    },
    selfChecks: mcqs,
  };
}

